import type { CSSProperties } from "react";
import type { ArchetypeId } from "../data/schema";

/**
 * Shared art + helpers for the personal-stats slides. The pixel art in
 * /wrapped/personal is generated by scripts/gen-personal-art.py.
 */

export const PERSONAL_ASSETS = "/wrapped/personal";
export const ARCHETYPE_BADGES_SRC = `${PERSONAL_ASSETS}/archetype-badges.png`;
export const PILLAR_SRC = `${PERSONAL_ASSETS}/pillar.png`;

/** Order of the 16px badges along archetype-badges.png. */
export const ARCHETYPE_ORDER: readonly ArchetypeId[] = [
  "ghost-member",
  "devs-star",
  "locked-in",
  "competitor",
  "party-animal",
  "all-rounder",
  "wildcard",
];

export function prefersReducedMotion(): boolean {
  return typeof matchMedia === "function" && matchMedia("(prefers-reduced-motion: reduce)").matches;
}

/** Joystix is monospaced at roughly 0.8em per glyph; pick the largest size that keeps `text` within `maxWidth`. */
export function fitJoystix(text: string, maxWidth: number, maxSize: number): number {
  return Math.min(maxSize, Math.floor(maxWidth / (Math.max(1, text.length) * 0.8)));
}

/** Small deterministic PRNG, so "random" scatters are identical every render and export. */
export function seeded(seed: number): () => number {
  let s = seed >>> 0;
  return () => {
    s = (s + 0x6d2b79f5) >>> 0;
    let t = s;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

interface ArchetypeBadgeProps {
  archetype: ArchetypeId;
  left: number;
  top: number;
  size: number;
  rotate?: number;
  style?: CSSProperties;
}

/** One archetype's pixel badge, cropped from the sprite sheet. */
export function ArchetypeBadge({ archetype, left, top, size, rotate, style }: ArchetypeBadgeProps) {
  const index = Math.max(0, ARCHETYPE_ORDER.indexOf(archetype));
  return (
    <div
      style={{
        position: "absolute",
        left,
        top,
        width: size,
        height: size,
        overflow: "hidden",
        transform: rotate ? `rotate(${rotate}deg)` : undefined,
        pointerEvents: "none",
        filter: "drop-shadow(0 8px 0 rgba(13,7,20,0.45))",
        ...style,
      }}
    >
      <img
        src={ARCHETYPE_BADGES_SRC}
        alt=""
        draggable={false}
        style={{
          position: "absolute",
          left: -index * size,
          top: 0,
          width: size * ARCHETYPE_ORDER.length,
          height: size,
          maxWidth: "none",
          imageRendering: "pixelated",
        }}
      />
    </div>
  );
}
